/**
 * Test audio, generated by global-setup with ffmpeg into e2e/.cache/media.
 * `media('song120.wav')` is the absolute path of one file.
 */
import path from 'node:path';
import { CACHE } from './app.mjs';

export const MEDIA_DIR = path.join(CACHE, 'media');
export const media = (name) => path.join(MEDIA_DIR, name);

// A 120 BPM groove: kick on every beat, offbeat hats, bass + a C-major-ish
// chord, so tempo/key analysis, onsets and the stems' filters all have
// something to find.
const SONG =
  "aevalsrc='0.6*sin(2*PI*55*t)*exp(-12*mod(t,0.5))+0.15*sin(2*PI*110*t)+0.12*sin(2*PI*261.63*t)+0.1*sin(2*PI*329.63*t)+0.08*sin(2*PI*392*t)+0.2*(random(0)-0.5)*exp(-40*mod(t+0.25,0.5))'";

export const MEDIA = {
  'song120.wav': ['-f', 'lavfi', '-i', `${SONG}:s=44100:d=24`, '-ac', '2'],
  'song120.mp3': ['-f', 'lavfi', '-i', `${SONG}:s=44100:d=24`, '-ac', '2', '-b:a', '192k'],
  // two bars at 100 BPM (4.8 s): a loop that fits whole bars
  'loop100.wav': ['-f', 'lavfi', '-i', "aevalsrc='0.5*sin(2*PI*98*t)*exp(-10*mod(t,0.6))+0.1*sin(2*PI*196*t)':s=44100:d=4.8", '-ac', '2'],
  'oneshot.wav': ['-f', 'lavfi', '-i', "aevalsrc='0.4*sin(2*PI*440*t)*exp(-6*t)':s=48000:d=1.5", '-ac', '1'],
  'clip.mp4': ['-f', 'lavfi', '-i', 'testsrc=d=6:s=320x240:r=10', '-f', 'lavfi', '-i', "aevalsrc='0.4*sin(2*PI*220*t)':s=44100:d=6", '-shortest', '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-c:a', 'aac'],
  // not audio at all: random bytes with an .mp3 name
  'not-audio.mp3': ['-f', 'lavfi', '-i', 'anoisesrc=d=0.05', '-f', 'u8', '-ar', '8000'],
  // over the 30-minute limit, tiny on disk
  'too-long.mp3': ['-f', 'lavfi', '-i', 'anullsrc=r=8000:cl=mono', '-t', '1870', '-c:a', 'libmp3lame', '-b:a', '8k'],
};
